'use strict';

function days(value) {
  return `${value} ${value === 1 ? 'day' : 'days'}`;
}

function choiceLabel(choice) {
  if (choice === 'expedite') return 'Expedite delivery';
  if (choice === 'help') return 'Assembly help';
  if (choice === 'both') return 'Expedite + help';
  return 'Wait / no intervention';
}

function targetText(finish, target) {
  if (finish > target) return `Misses target by ${days(finish - target)}`;
  if (finish === target) return 'Meets target exactly';
  return `Meets target with ${days(target - finish)} to spare`;
}

// Plain data API. Valid results contain parsed inputs, numeric finishes,
// per-option calculations, a calculated suggestion, and the fixed timeline.
// Invalid results retain this shape, with null calculations and no timeline.
function validate(values) {
  const empty = {
    valid: false, error: '', inputs: null, baselineFinish: null,
    delayedFinish: null, selectedFinish: null, savedDays: null,
    lateness: null, targetMet: null, options: [], suggestedChoice: null,
    suggestionReason: '', bottleneck: '', decisionNote: '', schedule: null
  };
  const fields = [
    {id: 'delay-days', label: 'Delivery delay', min: 0, max: 10},
    {id: 'target-day', label: 'Target finish day', min: 1, max: 40},
    {id: 'delivery-days', label: 'Original delivery duration', min: 1, max: 10},
    {id: 'prepare-days', label: 'Preparation duration', min: 1, max: 10},
    {id: 'assembly-days', label: 'Original assembly duration', min: 1, max: 10}
  ];
  const parsed = {};
  for (const field of fields) {
    const raw = values && typeof values[field.id] === 'string' ? values[field.id].trim() : null;
    if (raw === null || !/^(0|[1-9][0-9]*)$/.test(raw) || raw.length > 2 ||
        Number(raw) < field.min || Number(raw) > field.max) {
      return {...empty, error: `${field.label} must be a whole number from ${field.min} to ${field.max}, entered as text without leading zeros.`};
    }
    parsed[field.id] = Number(raw);
  }
  const choices = ['none', 'expedite', 'help', 'both'];
  const choice = values && typeof values.choice === 'string' ? values.choice.trim() : null;
  if (!choices.includes(choice)) {
    return {...empty, error: 'Recovery choice must be none, expedite, help, or both.'};
  }
  const inputs = {
    delayDays: parsed['delay-days'], targetDay: parsed['target-day'], choice,
    deliveryDays: parsed['delivery-days'], prepareDays: parsed['prepare-days'],
    assemblyDays: parsed['assembly-days']
  };
  const baselineStart = 1 + Math.max(inputs.deliveryDays, inputs.prepareDays);
  const baselineFinish = baselineStart + inputs.assemblyDays + 1;
  const delayedFinish = 2 + Math.max(inputs.deliveryDays + inputs.delayDays, inputs.prepareDays) + inputs.assemblyDays;
  const options = [];
  for (const optionChoice of choices) {
    const expedited = optionChoice === 'expedite' || optionChoice === 'both';
    const helped = optionChoice === 'help' || optionChoice === 'both';
    const deliveryDays = inputs.deliveryDays + inputs.delayDays - (expedited ? Math.min(2, inputs.delayDays) : 0);
    const assemblyDays = helped ? Math.max(1, inputs.assemblyDays - 1) : inputs.assemblyDays;
    const assemblyStart = 1 + Math.max(deliveryDays, inputs.prepareDays);
    const finish = assemblyStart + assemblyDays + 1;
    options.push({
      choice: optionChoice, label: choiceLabel(optionChoice),
      interventions: optionChoice === 'none' ? 0 : optionChoice === 'both' ? 2 : 1,
      finish, savedDays: delayedFinish - finish,
      lateness: Math.max(0, finish - inputs.targetDay), targetMet: finish <= inputs.targetDay,
      deliveryDays, assemblyDays, assemblyStart
    });
  }
  const selected = options.find(option => option.choice === choice);
  const anyMeetTarget = options.some(option => option.targetMet);
  let suggestion = null;
  for (const option of options) {
    if (anyMeetTarget && !option.targetMet) continue;
    if (suggestion === null ||
        (anyMeetTarget && (option.interventions < suggestion.interventions ||
          (option.interventions === suggestion.interventions && option.finish < suggestion.finish))) ||
        (!anyMeetTarget && (option.finish < suggestion.finish ||
          (option.finish === suggestion.finish && option.interventions < suggestion.interventions)))) {
      suggestion = option;
    }
  }
  const suggestionReason = anyMeetTarget
    ? 'Fewest interventions among options meeting target; earlier finish breaks a tie.'
    : 'No option meets target. Earliest finish wins; fewer interventions breaks a tie.';
  let bottleneck = '';
  if (selected.deliveryDays > inputs.prepareDays) {
    bottleneck = `Delivery controls Assembly start at day ${selected.assemblyStart}; Preparation finishes at day ${1 + inputs.prepareDays}.`;
  } else if (selected.deliveryDays < inputs.prepareDays) {
    bottleneck = `Preparation controls Assembly start at day ${selected.assemblyStart}; Delivery finishes at day ${1 + selected.deliveryDays}.`;
  } else {
    bottleneck = `Delivery and Preparation both control Assembly start at day ${selected.assemblyStart}.`;
  }
  const expeditedDelivery = inputs.deliveryDays + inputs.delayDays - Math.min(2, inputs.delayDays);
  if (inputs.prepareDays >= inputs.deliveryDays + inputs.delayDays) {
    bottleneck += ' Expediting Delivery cannot bring Assembly forward because Preparation finishes at the same time or later.';
  } else if (inputs.prepareDays > expeditedDelivery) {
    bottleneck += ' After expediting, Preparation becomes the limit; further Delivery savings cannot bring Assembly forward.';
  } else if (inputs.delayDays === 0) {
    bottleneck += ' There is no added delivery delay for expediting to remove.';
  }
  const decisionNote = `Selected: ${selected.label}. Finish day ${selected.finish}; ${targetText(selected.finish, inputs.targetDay).toLowerCase()}; saves ${days(selected.savedDays)} versus waiting. Calculated suggestion: ${suggestion.label}, finish day ${suggestion.finish}. ${suggestionReason} Apply it only after checking that the interventions are feasible; this comparison does not guarantee delivery or staff availability.`;
  const horizon = Math.max(baselineFinish, delayedFinish, inputs.targetDay);
  const rows = [
    {id: 'brief', label: 'Confirm brief', start: 0, end: 1, baselineStart: 0, baselineEnd: 1},
    {id: 'delivery', label: 'Delivery', start: 1, end: 1 + selected.deliveryDays, baselineStart: 1, baselineEnd: 1 + inputs.deliveryDays},
    {id: 'prepare', label: 'Prepare workspace', start: 1, end: 1 + inputs.prepareDays, baselineStart: 1, baselineEnd: 1 + inputs.prepareDays},
    {id: 'assemble', label: 'Assembly', start: selected.assemblyStart, end: selected.assemblyStart + selected.assemblyDays, baselineStart, baselineEnd: baselineStart + inputs.assemblyDays},
    {id: 'review', label: 'Review', start: selected.finish - 1, end: selected.finish, baselineStart: baselineFinish - 1, baselineEnd: baselineFinish}
  ];
  return {
    valid: true, error: '', inputs, baselineFinish, delayedFinish,
    selectedFinish: selected.finish, savedDays: selected.savedDays,
    lateness: selected.lateness, targetMet: selected.targetMet, options,
    suggestedChoice: suggestion.choice, suggestionReason, bottleneck, decisionNote,
    schedule: {text: `Baseline finish day ${baselineFinish}; selected finish day ${selected.finish}; target day ${inputs.targetDay}.`, timeline: {unit: 'days', horizon, rows}}
  };
}

function handleMessage(msg) {
  let workValues = {...(msg && msg.values)};
  const patches = [];
  const presets = {
    'example-delay': {'delay-days': '2', 'target-day': '7', choice: 'none', 'delivery-days': '3', 'prepare-days': '2', 'assembly-days': '2'},
    'example-preparation': {'delay-days': '2', 'target-day': '8', choice: 'none', 'delivery-days': '3', 'prepare-days': '6', 'assembly-days': '2'},
    reset: {'delay-days': '0', 'target-day': '7', choice: 'none', 'delivery-days': '3', 'prepare-days': '2', 'assembly-days': '2'}
  };
  if (msg && msg.type === 'event' && msg.event === 'click') {
    if (msg.id === 'example-delay' || msg.id === 'example-preparation' || msg.id === 'reset') {
      workValues = {...presets[msg.id]};
      for (const inputId of ['delay-days', 'target-day', 'choice', 'delivery-days', 'prepare-days', 'assembly-days']) {
        patches.push({id: inputId, value: workValues[inputId]});
      }
    } else if (msg.id === 'use-suggestion') {
      const current = validate(workValues);
      if (current.valid) {
        workValues.choice = current.suggestedChoice;
        patches.push({id: 'choice', value: workValues.choice});
      }
    }
  }
  const result = validate(workValues);
  patches.push({id: 'baseline-finish', text: result.valid ? `Day ${result.baselineFinish}` : ''});
  patches.push({id: 'delayed-finish', text: result.valid ? `Day ${result.delayedFinish}` : ''});
  patches.push({id: 'selected-finish', text: result.valid ? `Day ${result.selectedFinish}` : ''});
  patches.push({id: 'target-status', text: result.valid ? `${targetText(result.selectedFinish, result.inputs.targetDay)}. Saves ${days(result.savedDays)} versus waiting.` : ''});
  for (const optionChoice of ['none', 'expedite', 'help', 'both']) {
    const option = result.options.find(item => item.choice === optionChoice);
    patches.push({id: `option-${optionChoice}`, text: option ? `Day ${option.finish}; saves ${days(option.savedDays)}; ${targetText(option.finish, result.inputs.targetDay).toLowerCase()}; ${option.interventions} ${option.interventions === 1 ? 'intervention' : 'interventions'}.` : ''});
  }
  patches.push({id: 'bottleneck', text: result.bottleneck});
  patches.push({id: 'decision-note', text: result.decisionNote});
  if (result.schedule) {
    patches.push({id: 'schedule', text: result.schedule.text, timeline: result.schedule.timeline});
  } else {
    patches.push({id: 'schedule', text: ''});
  }
  patches.push({id: 'error', text: result.error});
  patches.push({id: 'use-suggestion', disabled: !result.valid});
  return patches;
}

'use strict';

// Authored product checks for the isolated assertion runner. Static admission
// parses this file; it must never be evaluated/imported by the local host.
const defaults = {'delay-days': '2', 'target-day': '7', choice: 'none', 'delivery-days': '3', 'prepare-days': '2', 'assembly-days': '2'};
const inputIds = ['delay-days', 'target-day', 'choice', 'delivery-days', 'prepare-days', 'assembly-days'];
const outputIds = ['baseline-finish', 'delayed-finish', 'selected-finish', 'target-status', 'option-none', 'option-expedite', 'option-help', 'option-both', 'bottleneck', 'decision-note', 'schedule', 'error'];
const taskIds = ['brief', 'delivery', 'prepare', 'assemble', 'review'];
const choices = ['none', 'expedite', 'help', 'both'];

function patchFor(patches, id) {
  const found = patches.filter(patch => patch.id === id);
  assert.equal(found.length, 1);
  return found[0];
}

function checkOutputSet(patches) {
  assert.deepEqual(patches.filter(patch => outputIds.includes(patch.id)).map(patch => patch.id).sort(), [...outputIds].sort());
  assert.ok(patches.every(patch => outputIds.includes(patch.id) || inputIds.includes(patch.id) || patch.id === 'use-suggestion'));
}

function checkResult(values, baseline, delayed, finishes, suggestion) {
  const result = validate(values);
  assert.equal(result.valid, true);
  assert.equal(result.error, '');
  assert.equal(result.baselineFinish, baseline);
  assert.equal(result.delayedFinish, delayed);
  assert.deepEqual(result.options.map(option => option.choice), choices);
  assert.deepEqual(result.options.map(option => option.finish), finishes);
  assert.deepEqual(result.options.map(option => option.interventions), [0, 1, 1, 2]);
  assert.equal(result.suggestedChoice, suggestion);
  const selectedIndex = choices.indexOf(values.choice.trim());
  assert.equal(result.selectedFinish, finishes[selectedIndex]);
  assert.equal(result.savedDays, delayed - result.selectedFinish);
  assert.equal(result.lateness, Math.max(0, result.selectedFinish - Number(values['target-day'])));
  assert.equal(result.targetMet, result.selectedFinish <= Number(values['target-day']));
  assert.equal(result.inputs.choice, values.choice.trim());
  assert.ok(result.decisionNote.includes('Selected:'));
  assert.ok(result.decisionNote.includes('Calculated suggestion:'));
  assert.ok(result.suggestionReason.length > 0);
  assert.equal(result.schedule.timeline.unit, 'days');
  assert.equal(result.schedule.timeline.horizon, Math.max(baseline, delayed, Number(values['target-day'])));
  assert.deepEqual(result.schedule.timeline.rows.map(row => row.id), taskIds);
  assert.equal(result.schedule.timeline.rows.length, 5);
  for (const row of result.schedule.timeline.rows) {
    assert.deepEqual(Object.keys(row).sort(), ['baselineEnd', 'baselineStart', 'end', 'id', 'label', 'start']);
    assert.ok(Number.isInteger(row.start) && Number.isInteger(row.end));
    assert.ok(row.start >= 0 && row.end > row.start && row.end <= result.schedule.timeline.horizon);
    assert.ok(row.baselineStart >= 0 && row.baselineEnd > row.baselineStart && row.baselineEnd <= result.schedule.timeline.horizon);
  }
  return result;
}

// Contract examples, with literal expected results independent of implementation.
const initial = checkResult(defaults, 7, 9, [9, 7, 8, 6], 'expedite');
assert.equal(initial.savedDays, 0);
assert.equal(initial.lateness, 2);
assert.deepEqual(initial.schedule.timeline.rows, [
  {id: 'brief', label: 'Confirm brief', start: 0, end: 1, baselineStart: 0, baselineEnd: 1},
  {id: 'delivery', label: 'Delivery', start: 1, end: 6, baselineStart: 1, baselineEnd: 4},
  {id: 'prepare', label: 'Prepare workspace', start: 1, end: 3, baselineStart: 1, baselineEnd: 3},
  {id: 'assemble', label: 'Assembly', start: 6, end: 8, baselineStart: 4, baselineEnd: 6},
  {id: 'review', label: 'Review', start: 8, end: 9, baselineStart: 6, baselineEnd: 7}
]);
for (const choice of choices) {
  const result = checkResult({...defaults, choice}, 7, 9, [9, 7, 8, 6], 'expedite');
  assert.deepEqual(result.schedule.timeline.rows.map(row => [row.baselineStart, row.baselineEnd]), [[0, 1], [1, 4], [1, 3], [4, 6], [6, 7]]);
}
const preparation = {...defaults, 'target-day': '8', 'prepare-days': '6'};
const preparationResult = checkResult(preparation, 10, 10, [10, 10, 9, 9], 'help');
assert.equal(preparationResult.lateness, 2);
assert.ok(preparationResult.bottleneck.includes('Preparation controls'));
assert.ok(preparationResult.bottleneck.includes('cannot bring Assembly forward'));
checkResult({...defaults, 'delay-days': '0'}, 7, 7, [7, 7, 6, 6], 'none');

// Ranking: intervention count precedes speed when meeting target; earliest
// finish precedes count when every option misses. Stable order resolves ties.
checkResult({...defaults, 'target-day': '9'}, 7, 9, [9, 7, 8, 6], 'none');
checkResult({...defaults, 'target-day': '8'}, 7, 9, [9, 7, 8, 6], 'expedite');
checkResult({...defaults, 'target-day': '5'}, 7, 9, [9, 7, 8, 6], 'both');
checkResult({...defaults, 'delay-days': '1', 'target-day': '7'}, 7, 8, [8, 7, 7, 6], 'expedite');
checkResult({...defaults, 'assembly-days': '1'}, 6, 8, [8, 6, 8, 6], 'expedite');
checkResult({'delay-days': '10', 'target-day': '1', choice: 'both', 'delivery-days': '10', 'prepare-days': '10', 'assembly-days': '10'}, 22, 32, [32, 30, 31, 29], 'both');
checkResult({'delay-days': '0', 'target-day': '40', choice: 'none', 'delivery-days': '1', 'prepare-days': '1', 'assembly-days': '1'}, 4, 4, [4, 4, 4, 4], 'none');
const whitespace = {'delay-days': ' \t2\n', 'target-day': ' 7 ', choice: '\nexpedite ', 'delivery-days': ' 3 ', 'prepare-days': '\t2', 'assembly-days': '2\r\n'};
checkResult(whitespace, 7, 9, [9, 7, 8, 6], 'expedite');
const tied = validate({...defaults, 'delay-days': '0', 'prepare-days': '3'});
assert.ok(tied.bottleneck.includes('both control'));

// Every response recomputes from all six current fields. Edits never silently
// select the suggestion, and timeline baseline dates ignore choice and delay.
for (const event of ['input', 'change']) {
  for (const inputId of inputIds) {
    const patches = handleMessage({type: 'event', event, id: inputId, values: defaults});
    checkOutputSet(patches);
    assert.equal(patchFor(patches, 'selected-finish').text, 'Day 9');
    assert.equal(patchFor(patches, 'error').text, '');
    assert.equal(patchFor(patches, 'use-suggestion').disabled, false);
    assert.ok(!patches.some(patch => patch.id === 'choice'));
  }
}
const initPatches = handleMessage({type: 'init', values: defaults});
checkOutputSet(initPatches);
assert.equal(patchFor(initPatches, 'baseline-finish').text, 'Day 7');
assert.equal(patchFor(initPatches, 'delayed-finish').text, 'Day 9');
assert.equal(patchFor(initPatches, 'selected-finish').text, 'Day 9');
assert.ok(patchFor(initPatches, 'target-status').text.includes('Misses target by 2 days'));
const changedDurations = handleMessage({type: 'event', event: 'input', id: 'assembly-days', values: {...defaults, 'assembly-days': '5', 'prepare-days': '6', 'delivery-days': '2', 'target-day': '14'}});
assert.equal(patchFor(changedDurations, 'baseline-finish').text, 'Day 13');
assert.equal(patchFor(changedDurations, 'selected-finish').text, 'Day 13');
assert.ok(patchFor(changedDurations, 'target-status').text.includes('1 day to spare'));
const noDelay = validate({...defaults, 'delay-days': '0'});
assert.deepEqual(noDelay.schedule.timeline.rows.map(row => [row.baselineStart, row.baselineEnd]), initial.schedule.timeline.rows.map(row => [row.baselineStart, row.baselineEnd]));

// Strict lexical validation and type rejection, with complete stale clearing.
function assertInvalid(values, fieldLabel) {
  const result = validate(values);
  assert.equal(result.valid, false);
  assert.ok(result.error.length > 0);
  if (fieldLabel) assert.ok(result.error.includes(fieldLabel));
  assert.equal(result.inputs, null);
  for (const key of ['baselineFinish', 'delayedFinish', 'selectedFinish', 'savedDays', 'lateness', 'targetMet', 'suggestedChoice', 'schedule']) assert.equal(result[key], null);
  assert.deepEqual(result.options, []);
  assert.equal(result.bottleneck, '');
  assert.equal(result.decisionNote, '');
  const patches = handleMessage({type: 'event', event: 'input', id: 'delay-days', values});
  checkOutputSet(patches);
  for (const outputId of outputIds) {
    const patch = patchFor(patches, outputId);
    if (outputId === 'error') assert.ok(patch.text.length > 0);
    else assert.deepEqual(patch, {id: outputId, text: ''});
  }
  assert.equal(patchFor(patches, 'use-suggestion').disabled, true);
  const clicked = handleMessage({type: 'event', event: 'click', id: 'use-suggestion', values});
  assert.ok(!clicked.some(patch => patch.id === 'choice'));
}
const numericIds = ['delay-days', 'target-day', 'delivery-days', 'prepare-days', 'assembly-days'];
const labels = ['Delivery delay', 'Target finish day', 'Original delivery duration', 'Preparation duration', 'Original assembly duration'];
for (let index = 0; index < numericIds.length; index++) {
  for (const bad of ['', ' ', '+1', '-1', '1.0', '1e0', 'Infinity', 'NaN', '01', '00', '１', '١', '1 0', '1\n0', undefined, null, 1, true, [], {}]) {
    assertInvalid({...defaults, [numericIds[index]]: bad}, labels[index]);
  }
  const missing = {...defaults};
  delete missing[numericIds[index]];
  assertInvalid(missing, labels[index]);
}
assertInvalid({...defaults, 'delay-days': '11'}, 'Delivery delay');
assertInvalid({...defaults, 'target-day': '0'}, 'Target finish day');
assertInvalid({...defaults, 'target-day': '41'}, 'Target finish day');
for (const inputId of ['delivery-days', 'prepare-days', 'assembly-days']) {
  assertInvalid({...defaults, [inputId]: '0'});
  assertInvalid({...defaults, [inputId]: '11'});
}
for (const bad of ['', 'NONE', 'Expedite', 'wait', 'none help', undefined, null, 0, true, [], {}]) assertInvalid({...defaults, choice: bad}, 'Recovery choice');
assertInvalid(null);
assertInvalid(undefined);

// Presets restore every visible input before recomputing, even when all six
// prior fields are invalid. This is authored source, not a host execution gate.
const presetValues = [
  {id: 'example-delay', values: defaults, finish: 'Day 9'},
  {id: 'example-preparation', values: preparation, finish: 'Day 10'},
  {id: 'reset', values: {...defaults, 'delay-days': '0'}, finish: 'Day 7'}
];
const invalidValues = {'delay-days': '', 'target-day': '', choice: 'invalid', 'delivery-days': '', 'prepare-days': '', 'assembly-days': ''};
for (const preset of presetValues) {
  const patches = handleMessage({type: 'event', event: 'click', id: preset.id, values: invalidValues});
  assert.deepEqual(patches.slice(0, 6), inputIds.map(inputId => ({id: inputId, value: preset.values[inputId]})));
  checkOutputSet(patches);
  assert.equal(patchFor(patches, 'selected-finish').text, preset.finish);
  assert.equal(patchFor(patches, 'error').text, '');
  assert.equal(patchFor(patches, 'use-suggestion').disabled, false);
  assert.equal(patchFor(patches, 'schedule').timeline.rows.length, 5);
}
const applied = handleMessage({type: 'event', event: 'click', id: 'use-suggestion', values: defaults});
assert.deepEqual(applied[0], {id: 'choice', value: 'expedite'});
assert.equal(patchFor(applied, 'selected-finish').text, 'Day 7');
assert.ok(patchFor(applied, 'target-status').text.includes('Meets target exactly'));
assert.ok(patchFor(applied, 'decision-note').text.includes('Selected: Expedite delivery.'));
const appliedPreparation = handleMessage({type: 'event', event: 'click', id: 'use-suggestion', values: preparation});
assert.deepEqual(appliedPreparation[0], {id: 'choice', value: 'help'});
assert.equal(patchFor(appliedPreparation, 'selected-finish').text, 'Day 9');
assert.ok(patchFor(appliedPreparation, 'target-status').text.includes('Misses target by 1 day'));
const recovered = handleMessage({type: 'event', event: 'change', id: 'delay-days', values: defaults});
assert.equal(patchFor(recovered, 'error').text, '');
assert.equal(patchFor(recovered, 'use-suggestion').disabled, false);
assert.equal(patchFor(recovered, 'schedule').timeline.rows.length, 5);
